def taxonomy_discovery_metrics(y_true: List[Dict[str, str]], y_pred: List[Dict[str, str]]) -> Dict[str, float | int]:
    total_predicted = len(y_pred)
    total_ground_truth = len(y_true)
    # Convert ground truth and predictions to sets of tuples for easy comparison
    ground_truth_set = {(item["parent"].lower(), item["child"].lower()) for item in y_true}
    predictions_set = {(item["parent"].lower(), item["child"].lower()) for item in y_pred}
    # Calculate correctly predicted pairs (intersection of sets)
    correct_predictions = ground_truth_set.intersection(predictions_set)
    total_correct = len(correct_predictions)
    # Calculate precision, recall, and F1-score
    precision = total_correct / total_predicted if total_predicted > 0 else 0
    recall = total_correct / total_ground_truth if total_ground_truth > 0 else 0
    if precision + recall > 0:
        f1_score = 2 * (precision * recall) / (precision + recall)
    else:
        f1_score = 0
    return {
        "f1_score": f1_score,
        "precision": precision,
        "recall": recall,
        "total_correct": total_correct,
        "total_predicted": total_predicted,
        "total_ground_truth": total_ground_truth
    }

def _load(self, path: str, visited: Optional[set] = None) -> None:
    if visited is None:
        visited = set()
    if path in visited:
        return
    visited.add(path)

    self.rdf_graph.parse(path)

    if not self.contains_imports():
        return

    # Process owl:imports
    for ontology in self.rdf_graph.subjects(RDF.type, OWL.Ontology):
        for import_def in self.rdf_graph.objects(ontology, OWL.imports):
            import_uri = self._resolve_import_def(import_def)

            if import_uri:
                try:
                    self._load(import_uri, visited)
                except Exception as e:
                    logger.error(f"Failed to load import {import_uri}: {str(e)}")
                    pass
            else:
                logger.warning(f"Could not resolve import: {import_def}")
                pass


